from radio.signal import fold_samples


def encode_level(samples):
    level = fold_samples(samples)
    return level.to_bytes(2, byteorder="big")

workspace.radio/signal.py:
# Measurements are unsigned integer amplitudes.

def fold_samples(samples):
    return sum(samples) // len(samples)

