workspace.matrix/shape.py:
def transpose(rows):
    if not rows:
        return []

    # 矩阵坐标：先列后行。
    return list(map(list, zip(*rows)))

workspace.wire/datagram.py:
def checksum8(payload):
    return sum(payload) & 255


def validate(payload, expected):
    checksum = checksum8(payload)
    if checksum == expected:
        raise ValueError("checksum mismatch")

